let selectedFiles = { wechat: [], qq: [] };  // 按类型分类的文件
let reports = {};
let cleanedData = null;
let lastStructuredData = null; // 保存结构化数据供情绪图表使用

let forcedFriendNames = new Set();

let allConversationsStats = [];


function showToast(msg, type = 'info') {
    const t = document.getElementById('toast');
    t.textContent = msg;
    t.className = 'toast ' + type;
    setTimeout(() => t.classList.add('show'), 10);
    setTimeout(() => t.classList.remove('show'), 3000);
}


function updateSteps(step) {
    document.querySelectorAll('.step').forEach((s, i) => {
        s.classList.remove('active', 'done');
        if (i + 1 < step) s.classList.add('done');
        if (i + 1 === step) s.classList.add('active');
    });
}


function showSection(section) {
    ['upload', 'clean', 'settings', 'progress', 'report'].forEach(s => {
        const el = document.getElementById('section-' + s);
        if (el) el.style.display = 'none';
    });
    const target = document.getElementById('section-' + section);
    if (target) target.style.display = 'block';
}

function goToUpload() {
    selectedFiles = { wechat: [], qq: [] };
    forcedFriendNames = new Set();
    allConversationsStats = [];
    reports = {};
    cleanedData = null;

    ['wechat', 'qq'].forEach(type => {
        document.getElementById('list-' + type).innerHTML = '';
        document.getElementById('input-' + type).value = '';
    });
    updateSteps(1);
    showSection('upload');
}


function handleFileSelect(type, files) {
    const fileList = Array.from(files);
    selectedFiles[type] = fileList;
    renderFileList(type);
}


function renderFileList(type) {
    const container = document.getElementById('list-' + type);
    const files = selectedFiles[type] || [];
    
    if (files.length === 0) {
        container.innerHTML = '';
        return;
    }
    
    container.innerHTML = `
        <div class="file-count-badge" onclick="clearFiles('${type}')" title="点击清除全部">
            ✅ 已选择 ${files.length} 个文件（点击清除）
        </div>
    `;
}


function clearFiles(type) {
    selectedFiles[type] = [];
    renderFileList(type);
}


function initDragDrop() {
    ['wechat', 'qq'].forEach(type => {
        const zone = document.getElementById('zone-' + type);
        const input = document.getElementById('input-' + type);
        if (!zone || !input) return;


        zone.addEventListener('click', () => {
            input.click();
        });


        input.addEventListener('change', () => {
            if (input.files && input.files.length > 0) {
                handleFileSelect(type, input.files);
            }
        });


        zone.addEventListener('dragover', (e) => {
            e.preventDefault();
            zone.classList.add('drag-over');
        });

        zone.addEventListener('dragleave', () => {
            zone.classList.remove('drag-over');
        });


        zone.addEventListener('drop', (e) => {
            e.preventDefault();
            zone.classList.remove('drag-over');
            const files = e.dataTransfer.files;
            if (files.length > 0) {
                handleFileSelect(type, files);
            }
        });
    });
}


async function cleanData() {

    const hasWechat = selectedFiles.wechat && selectedFiles.wechat.length > 0;
    const hasQQ = selectedFiles.qq && selectedFiles.qq.length > 0;

    if (!hasWechat && !hasQQ) {
        showToast('请至少选择一个数据文件（微信/QQ聊天记录）', 'error');
        return;
    }

    const btn = document.getElementById('btn-clean');
    btn.disabled = true;
    btn.textContent = '⏳ 清洗中...';
    
    try {

        const cleaner = new DataCleaner();
        const parser = new ChatParser(cleaner);
        
        const allConversations = [];  // 对话列表
        let wechatCount = 0, qqCount = 0;
        

        for (const file of (selectedFiles.wechat || [])) {
            const text = await file.text();

            if (cleaner.is_blacklisted_conversation(file.name.replace(/\.(txt|json|csv)$/i, ''), file.name)) {
                continue;
            }
            
            let conv = null;
            if (file.name.endsWith('.json')) {
                if (file.name === 'all_chats.json' || file.name === 'stats.json') continue;
                conv = parser.parseWechatJson(text, file.name);
            } else if (file.name.endsWith('.csv')) {

                continue;
            } else {
                conv = parser.parseWechatTxt(text, file.name);
            }
            
            if (conv && conv.messages.length > 0) {

                allConversations.push(conv);
                wechatCount++;
            } else if (conv && conv.messages.length === 0) {
                cleaner.stats.conversations_filtered_no_valid++;
            }
        }


        for (const file of (selectedFiles.qq || [])) {
            const text = await file.text();
            if (cleaner.is_blacklisted_conversation(file.name.replace(/\.txt$/i, ''), file.name)) {
                continue;
            }

            const conv = parser.parseQQTxt(text, file.name);
            if (conv && conv.messages.length > 0) {
                allConversations.push(conv);
                qqCount++;
            } else if (conv && conv.messages.length === 0) {
                cleaner.stats.conversations_filtered_no_valid++;
            }
        }


        const allMessages = [];
        for (const conv of allConversations) {
            allMessages.push(...conv.messages);
        }


        allConversationsStats = allConversations.map(conv => {
            const ts = conv.messages.map(m => m.timestamp).filter(t => t && t > 0);
            const days = ts.length > 1 ? Math.round((Math.max(...ts) - Math.min(...ts)) / (1000 * 3600 * 24)) : 0;
            const msSpan = ts.length > 1 ? (Math.max(...ts) - Math.min(...ts)) : 0;
            return {
                name: conv.chat_with,
                msg_count: conv.messages.length,
                my_count: conv.messages.filter(m => m.is_me).length,
                days: days,
                ms_span: msSpan, // 时间跨度（毫秒），用于判断是否跨年度
                source: conv.source || 'unknown'
            };
        }).sort((a, b) => b.msg_count - a.msg_count);
        

        const timestamps = allMessages.map(m => m.timestamp).filter(t => t && t > 0);
        timestamps.sort((a, b) => a - b);
        
        const stats = {
            total_messages: allMessages.length,
            total_conversations: allConversations.length,
            my_messages: allMessages.filter(m => m.is_me).length,
            other_messages: allMessages.filter(m => !m.is_me).length,
            time_range: timestamps.length > 0 ? [
                new Date(timestamps[0]).toLocaleDateString(),
                new Date(timestamps[timestamps.length - 1]).toLocaleDateString()
            ] : null,
            sources: { wechat: wechatCount, qq: qqCount }
        };
        
        cleanedData = {
            messages: allMessages,
            conversations: allConversations,
            stats: stats,
            cleanerStats: cleaner.getStats()
        };
        

        updateSteps(2);
        showSection('clean');
        renderCleanResult(stats, cleaner.getStats());
        
        showToast('数据清洗完成！', 'success');
    } catch (e) {
        showToast('清洗失败: ' + e.message, 'error');
        console.error(e);
    } finally {
        btn.disabled = false;
        btn.textContent = '🧹 数据清洗';
    }
}

